    'about.value.passion.desc' => ['fr' => "L'informatique et la vie de campus : nos deux moteurs.", 'en' => 'Computer science and campus life: our two driving forces.', 'de' => 'Informatik und Campusleben: unsere zwei Antriebe.', 'es' => 'La informática y la vida del campus: nuestros dos motores.', 'zh' => '计算机与校园生活:我们的两大动力。', 'ja' => '情報科学とキャンパス生活:私たちの二つの原動力。', 'pl' => 'Informatyka i życie kampusu: nasze dwa silniki.'],
    'about.value.sharing'   => ['fr' => 'Partage', 'en' => 'Sharing', 'de' => 'Teilen', 'es' => 'Compartir', 'zh' => '分享', 'ja' => '共有', 'pl' => 'Dzielenie się'],
    'about.value.sharing.desc' => ['fr' => 'Transmettre, entraider, ouvrir des opportunités à tous.', 'en' => 'Passing on knowledge, helping each other, opening opportunities for everyone.', 'de' => 'Wissen weitergeben, einander helfen, allen Chancen eröffnen.', 'es' => 'Transmitir, ayudar, abrir oportunidades a todos.', 'zh' => '传授知识、互助,为每个人打开机会。', 'ja' => '知識を伝え、助け合い、すべての人に機会を開く。', 'pl' => 'Przekazywać wiedzę, pomagać, otwierać możliwości dla wszystkich.'],
    'about.stats.title'     => ['fr' => 'Des actions concrètes', 'en' => 'Concrete actions', 'de' => 'Konkrete Taten', 'es' => 'Acciones concretas', 'zh' => '切实的行动', 'ja' => '具体的な行動', 'pl' => 'Konkretne działania'],
    'about.cta.title'       => ['fr' => 'Envie de nous rejoindre ?', 'en' => 'Want to join us?', 'de' => 'Möchtest du dabei sein?', 'es' => '¿Quieres unirte a nosotros?', 'zh' => '想加入我们吗?', 'ja' => '私たちと一緒に活動しませんか?', 'pl' => 'Chcesz do nas dołączyć?'],

    /* Présentation — contenu structuré (en remplacement du CMS)        */
    'about.vision.title'    => ['fr' => 'Notre vision', 'en' => 'Our vision', 'de' => 'Unsere Vision', 'es' => 'Nuestra visión', 'zh' => '我们的愿景', 'ja' => '私たちのビジョン', 'pl' => 'Nasza wizja'],
    'about.vision.desc'     => ['fr' => "Nous croyons qu'un campus est avant tout une communauté. Notre vision : un lieu où chacun trouve sa place, où les idées prennent forme et où l'informatique rime avec convivialité.", 'en' => 'We believe a campus is, above all, a community. Our vision: a place where everyone fits in, where ideas take shape, and where computer science goes hand in hand with a friendly atmosphere.', 'de' => 'Wir glauben, dass ein Campus vor allem eine Gemeinschaft ist. Unsere Vision: ein Ort, an dem jeder seinen Platz findet, Ideen Gestalt annehmen und Informatik mit Geselligkeit einhergeht.', 'es' => 'Creemos que un campus es, ante todo, una comunidad. Nuestra visión: un lugar donde cada persona encuentra su sitio, donde las ideas toman forma y donde la informática va de la mano con la convivencia.', 'zh' => '我们相信,校园首先是一个社区。我们的愿景:一个让每个人都找到归属的地方,让创意成形,让计算机科学与人情味同行。', 'ja' => 'キャンパスは何よりもコミュニティだと私たちは信じています。私たちのビジョンは、誰もが居場所を見つけ、アイデアが形になり、情報科学と親しみやすさが両立する場所です。', 'pl' => 'Wierzymy, że kampus to przede wszystkim społeczność. Nasza wizja: miejsce, w którym każdy odnajduje swoje miejsce, pomysły nabierają kształtu, a informatyka idzie w parze z życzliwością.'],
    'about.spaces.eyebrow'  => ['fr' => 'Nos espaces', 'en' => 'Our spaces', 'de' => 'Unsere Räume', 'es' => 'Nuestros espacios', 'zh' => '我们的空间', 'ja' => '私たちの空間', 'pl' => 'Nasze przestrzenie'],
    'about.spaces.title'    => ['fr' => 'Des espaces pour tous', 'en' => 'Spaces for everyone', 'de' => 'Räume für alle', 'es' => 'Espacios para todos', 'zh' => '人人可享的空间', 'ja' => 'すべての人のための空間', 'pl' => 'Przestrzenie dla każdego'],
    'about.spaces.desc'     => ['fr' => 'Des lieux pensés pour étudier, échanger et se détendre entre deux cours.', 'en' => 'Places designed to study, chat and unwind between classes.', 'de' => 'Orte zum Lernen, Austauschen und Entspannen zwischen den Vorlesungen.', 'es' => 'Lugares pensados para estudiar, charlar y desconectar entre clases.', 'zh' => '为课间学习、交流和放松而设计的空间。', 'ja' => '授業の合間に勉強したり、語り合ったり、リラックスしたりするために設計された場所。', 'pl' => 'Miejsca stworzone do nauki, rozmów i relaksu między zajęciami.'],
    'about.spaces.free'     => ['fr' => "En accès libre pendant nos horaires d'ouverture : travail en groupe, détente, discussions, tout est prévu.", 'en' => 'Open access during our opening hours: group work, relaxation, chats — everything is covered.', 'de' => 'Während unserer Öffnungszeiten frei zugänglich: Gruppenarbeit, Entspannung, Gespräche — an alles ist gedacht.', 'es' => 'Acceso libre durante nuestro horario de apertura: trabajo en grupo, descanso, charlas, todo está pensado.', 'zh' => '在我们开放时段内自由进出:小组作业、放松、交流,一应俱全。', 'ja' => '開館時間中は自由に利用可能:グループ作業、リラックス、会話、すべて揃っています。', 'pl' => 'Dostęp swobodny w godzinach otwarcia: praca w grupie, relaks, rozmowy — wszystko jest zapewnione.'],
    'about.spaces.local'    => ['fr' => "Dans le local de l'association, retrouvez la cafétéria à prix étudiant, des jeux de société et des membres prêts à donner un coup de main.", 'en' => "In the association's room you'll find the student-priced cafeteria, board games and members ready to help out.", 'de' => 'Im Vereinsraum findest du die Cafeteria zu Studierendenpreisen, Gesellschaftsspiele und Mitglieder, die gerne helfen.', 'es' => 'En el local de la asociación encontrarás la cafetería a precio de estudiante, juegos de mesa y miembros dispuestos a echar una mano.', 'zh' => '在协会活动室,你可以找到学生价的咖啡馆、桌游,以及乐于助人的成员。', 'ja' => '協会の部屋には、学生価格のカフェテリア、ボードゲーム、そして助け合いを惜しまないメンバーがいます。', 'pl' => 'W lokalu stowarzyszenia znajdziesz kafeterię w cenach studenckich, gry planszowe oraz członków gotowych do pomocy.'],
    'about.contact.title'   => ['fr' => 'Coordonnées', 'en' => 'Contact details', 'de' => 'Kontaktangaben', 'es' => 'Datos de contacto', 'zh' => '联系方式', 'ja' => '連絡先', 'pl' => 'Dane kontaktowe'],
    'about.contact.label'   => ['fr' => 'Contact', 'en' => 'Contact', 'de' => 'Kontakt', 'es' => 'Contacto', 'zh' => '联系方式', 'ja' => 'お問い合わせ', 'pl' => 'Kontakt'],
