    'about.events.eyebrow'  => ['fr' => 'Agenda', 'en' => 'Agenda', 'de' => 'Termine', 'es' => 'Agenda', 'zh' => '日程', 'ja' => '予定', 'pl' => 'Agenda'],
    'about.events.title'    => ['fr' => 'Nos événements phares', 'en' => 'Our flagship events', 'de' => 'Unsere Highlight-Events', 'es' => 'Nuestros eventos estrella', 'zh' => '我们的招牌活动', 'ja' => '私たちの代表的なイベント', 'pl' => 'Nasze flagowe wydarzenia'],
    'about.events.intro'    => ['fr' => "Tout au long de l'année, nous animons le campus avec des moments faits pour se retrouver et souffler.", 'en' => 'All year round, we bring the campus to life with moments designed to bring people together and catch their breath.', 'de' => 'Das ganze Jahr über beleben wir den Campus mit Momenten, die zum Zusammenkommen und Durchatmen einladen.', 'es' => 'A lo largo del año, animamos el campus con momentos pensados para reunitednos y desconectar.', 'zh' => '全年,我们用一个个让彼此相聚、喘口气的时刻,让校园鲜活起来。', 'ja' => '一年を通して、みんなが集まり、ひと息つける瞬間でキャンパスを盛り上げます。', 'pl' => 'Przez cały rok ożywiamy kampus chwilami stworzonymi, by się spotykać i odetchnąć.'],
    'about.events.nuitinfo.title' => ['fr' => 'La Nuit de l\'Info', 'en' => 'Nuit de l\'Info', 'de' => 'Die Nuit de l\'Info', 'es' => 'La Nuit de l\'Info', 'zh' => '信息之夜', 'ja' => 'Nuit de l\'Info(情報の夜)', 'pl' => 'Nuit de l\'Info'],
    'about.events.nuitinfo.desc' => ['fr' => 'Le marathon de programmation national : une nuit pour coder, créer et relever des défis en équipe.', 'en' => 'The national programming marathon: a night to code, create and tackle challenges as a team.', 'de' => 'Der nationale Programmier-Marathon: eine Nacht zum Programmieren, Kreieren und für das Meistern von Herausforderungen im Team.', 'es' => 'El maratón nacional de programación: una noche para programar, crear y superar retos en equipo.', 'zh' => '全国编程马拉松:用一夜的时间,团队一起编码、创造、迎接挑战。', 'ja' => '全国プログラミングマラソン:チームでコードを書き、創り、課題に挑戦する一晩。', 'pl' => 'Krajowy maraton programowania: noc na kodowanie, tworzenie i pokonywanie wyzwań w zespole.'],
    'about.events.afterworks.title' => ['fr' => 'Afterworks', 'en' => 'Afterworks', 'de' => 'Afterworks', 'es' => 'Afterworks', 'zh' => '下班后聚会', 'ja' => 'アフターワーク', 'pl' => 'Afterworks'],
    'about.events.afterworks.desc' => ['fr' => "Des moments conviviaux en fin de journée pour souffler et faire connaissance autour d'un verre.", 'en' => 'Friendly moments at the end of the day to unwind and get to know each other over a drink.', 'de' => 'Gesellige Momente am Tagesende zum Durchatmen und Kennenlernen bei einem Drink.', 'es' => 'Momentos agradables al final del día para desconectar y conocerse alrededor de una bebida.', 'zh' => '在一天结束时,用轻松的时刻放松彼此、喝杯东西互相认识。', 'ja' => '一日の終わりに、ひと息つきながら一杯囲んで親睦を深める和やかな時間。', 'pl' => 'Przyjemne chwile pod koniec dnia, by odetchnąć i lepiej się poznać przy drinku.'],
    'about.events.bbq.title' => ['fr' => 'Barbecues', 'en' => 'Barbecues', 'de' => 'Grillfeste', 'es' => 'Barbacoas', 'zh' => '烧烤', 'ja' => 'バーベキュー', 'pl' => 'Grille'],
    'about.events.bbq.desc' => ['fr' => 'Le rendez-vous gourmand du campus : bonne humeur et partage au menu.', 'en' => 'The campus tastiest get-together: good vibes and sharing on the menu.', 'de' => 'Das leckere Treffen auf dem Campus: gute Laune und Teilen stehen auf dem Programm.', 'es' => 'El encuentro más sabroso del campus: buen ambiente y compartir están en el menú.', 'zh' => '校园里的美味聚会:菜单上写着好心情与分享。', 'ja' => 'キャンパスで一番おいしい集い:メニューは楽しい雰囲気とシェア。', 'pl' => 'Najsmaczniejsze spotkanie na kampusie: w menu dobry nastrój i dzielenie się.'],
    'about.events.bowling.title' => ['fr' => 'Soirées bowling', 'en' => 'Bowling nights', 'de' => 'Bowling-Abende', 'es' => 'Noches de bolos', 'zh' => '保龄球之夜', 'ja' => 'ボウリングの夕べ', 'pl' => 'Wieczory kręgli'],
    'about.events.bowling.desc' => ['fr' => 'Des soirées ludiques pour se défier entre amis et changer d\'air.', 'en' => 'Fun nights to challenge each other among friends and get a change of scenery.', 'de' => 'Spielerische Abende, um sich unter Freunden zu messen und auf andere Gedanken zu kommen.', 'es' => 'Noches lúdicas para desafiar a tus amigos y cambiar de aires.', 'zh' => '充满乐趣的夜晚,在朋友间相互挑战、换换心情。', 'ja' => '友達と競い合い、気分転換できる楽しい夜。', 'pl' => 'Zabawne wieczory, by rywalizować z przyjaciółmi i zmienić otoczenie.'],
